
cc.Class({
    extends: require("LMSlots_Symbol_Base"),

    properties: {

    },

    // LIFE-CYCLE CALLBACKS:

    // onLoad () {},

    ShowRandomSymbol(){
        this._super();

        let cfg = cc.vv.gameData.getGameCfg();
        let id = this._id;
        if(id == 3){
            let data = {}
            if(Math.random() > 0.3){
                let randIdx = Global.random(1,cfg.bonusCoinMultList.length);
                data.coin = cfg.bonusCoinMultList[randIdx - 1] * cc.vv.gameData.GetTotalBet()
            } else {
                let randIdx = Math.random();
                let randList = [0.1,0.3,0.5];
                let jpId = 1;
                if(randIdx < randList[0]){
                    jpId = 4
                } else if(randIdx < randList[1]){
                    jpId = 3
                } else if(randIdx < randList[2]){
                    jpId = 2
                }
                data.jackpot = {id:jpId}
            }

            this.ShowById(id, data);
        }
    },


    //显示symbole
    ShowById:function(id,data) {
        this._super(id, data);

        this.setNum();
        this.setJp();

        if(data && id == 3){
            if(data.coin){
                this.setNum(data.coin);
            } else if(data.jackpot){
                this.setJp(data.jackpot.id)
            }
        }
    },

    setNum(val){
        let lbl = cc.find("lbl", this.node);
        if(lbl){
            if(val){
                lbl.active = true;
                lbl.getComponent(cc.Label).string =  Global.formatNumShort(val,0);
            } else {
                lbl.active = false;
            }
        }
        this._bonusNum = val;
    },
    getNum(){
        return this._bonusNum
    },

    setJp(val){
        let jp = cc.find("jp", this.node);
        if(jp){
            if(val){
                jp.active = true;
                jp.getComponent("ImgSwitchCmp").setIndex(val-1);
            } else {
                jp.active = false;
            }
        }
    },

    // bonus图标停止动画
    playBonusStopAnim(){
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg()
        if(cfg.symbol[id] && cfg.symbol[id].win_node && cfg.symbol[id].stop_ani){
            this._state = "stop";
            if(this._showNode){
                this._showNode.active = false
            }
            this._showNode = cc.find(cfg.symbol[id].win_node,this.node)
            this._showNode.active = true

            if(cfg.symbol[id].stop_ani.name != ""){
                this.node.zIndex = cfg.symbol[id].stop_ani.zIndex - this._symbolIdx  + this._reelIdx*10;
                let nodeSp = this._showNode.getComponent(sp.Skeleton)
                if(nodeSp){
                    nodeSp.setAnimation(0,cfg.symbol[id].stop_ani.name,false)
                    if(cfg.symbol[id].idle_ani){
                        nodeSp.addAnimation(0,cfg.symbol[id].idle_ani.name,true)
                    }
                }
            }
        }
    },

    playBonusIdleAnim(){
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg()
        if(cfg.symbol[id] && cfg.symbol[id].win_node && cfg.symbol[id].idle_ani){
            this._state = "stop";
            if(this._showNode){
                this._showNode.active = false
            }
            this._showNode = cc.find(cfg.symbol[id].win_node,this.node)
            this._showNode.active = true

            if(cfg.symbol[id].idle_ani.name != ""){
                this.node.zIndex = cfg.symbol[id].idle_ani.zIndex - this._symbolIdx  + this._reelIdx*10;
                let nodeSp = this._showNode.getComponent(sp.Skeleton)
                if(nodeSp){
                    nodeSp.setAnimation(0,cfg.symbol[id].idle_ani.name,true)
                }
            }
        }
    },

    playBonusTriAnim(bDouble,callback){
        let isPlay = false;
        let id = this._id;
        let cfg = cc.vv.gameData.getGameCfg();
        if(cfg.symbol[id] && cfg.symbol[id].win_node && cfg.symbol[id].trigger_ani){
            this._state = "trigger";
            if(this._showNode){
                this._showNode.active = false
            }
            let aniNode = this.setAnimationToTop(true)
            aniNode.active = true
            let topShowNode = cc.find(cfg.symbol[id].win_node,aniNode)
            topShowNode.active = true
            if(cfg.symbol[id].trigger_ani.name != ""){
                aniNode.zIndex = cfg.symbol[id].trigger_ani.zIndex - this._symbolIdx + this._reelIdx*10;
                isPlay = true
                let nodeSp = topShowNode.getComponent(sp.Skeleton);
                if (nodeSp) {
                    nodeSp.setAnimation(0, cfg.symbol[id].trigger_ani.name, false);
                    if(bDouble){
                        nodeSp.addAnimation(0, cfg.symbol[id].trigger_ani.name, false);
                    } else {
                        if(callback){
                            nodeSp.setCompleteListener(()=>{
                                callback();
                            })
                        }
                    }
                }
            }
        }
        return isPlay
    },

    // 上升图标、扩散图标变回bonus图标
    playBonusChangeAnim(data){
        let id = this._id;
        let cfg = cc.vv.gameData.getGameCfg();
        let cloneNode = cc.instantiate(this.node);
        cloneNode.parent = this._topAniNode;
        cloneNode.position = this._topAniNode.convertToNodeSpaceAR(this.node.convertToWorldSpaceAR(cc.v2(0,0)));
        // cloneNode.zIndex = this.node.zIndex+100;
        cloneNode.active = true;
        let topShowNode = cc.find(cfg.symbol[id].win_node,cloneNode);
        topShowNode.active = true;
        if(cfg.symbol[id].boom_ani.name != ""){
            let nodeSp = topShowNode.getComponent(sp.Skeleton);
            if (nodeSp) {
                nodeSp.setAnimation(0, cfg.symbol[id].boom_ani.name, false);
                nodeSp.setCompleteListener(()=>{
                    cloneNode.destroy();
                })
            }
        }
        this.setAnimationToTop(false);
        this.ShowById(3, data);
        this.playBonusBoom();
        this.playBonusIdleAnim()
    },

    playBonusBoom(){
        let id = this._id;
        let cfg = cc.vv.gameData.getGameCfg();
        if(cfg.symbol[id] && cfg.symbol[id].win_node){

            let nodeAni = this._showNode.getComponent(cc.Animation)
            if(nodeAni){
                nodeAni.play("b_boom_1")
            }
        }
    },

    playBonusExtraBoom(){
        let id = this._id;
        let cfg = cc.vv.gameData.getGameCfg();
        if(cfg.symbol[id] && cfg.symbol[id].win_node){

            let nodeAni = this._showNode.getComponent(cc.Animation)
            if(nodeAni){
                nodeAni.play("b_extra_boom")
            }
        }
    },
    playBonusJiesuan(){
        let id = this._id;
        let cfg = cc.vv.gameData.getGameCfg();
        if(cfg.symbol[id] ){

            let nodeAni = this._showNode.getComponent(cc.Animation)
            if(nodeAni){
                nodeAni.play("b_jiesuan")
            }
            this._showNode.getComponent(sp.Skeleton).setAnimation(0,"animation3",false)

        }
    },

    playBonusKuangAnim(bPlay){
        let id = this._id;
        let cfg = cc.vv.gameData.getGameCfg();
        if(cfg.symbol[id] && cfg.symbol[id].kuang_node){
            cc.find(cfg.symbol[id].kuang_node, this._showNode).active = bPlay;
        }
    },

    // update (dt) {},
});
